from collections import defaultdict
def solve(g):
    ss=defaultdict(list)
    for r,row in enumerate(g):
        for c,x in enumerate(row):
            if x: ss[x].append((r,c))
    out=[[0]*len(g[0]) for _ in g]
    # anchor: shape with largest color value keeps position; others align tops to anchor top
    anch=max(ss, key=lambda c: c)
    a_top=min(p[0] for p in ss[anch])
    for col,pts in ss.items():
        dr=a_top-min(p[0] for p in pts)
        for r,c in pts: out[r+dr][c]=col
    return out
